//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = 'ULDSTF15650.xml';
scwin.mm = "0"; //전체
scwin.filterCnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetYYYY = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "";
    for (var i = yyyy; i >= (yyyy - 5); i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;
    $c.stf.setObjectValue(cmb_YYYY, ToDay.getYear());
};
scwin.fn_SetMM = function() {
    var yy = 12;
    var str = "0^전체,";
    for (var i = yy; i >= 1; i--) {
        if ((i + '').length == 1) str += ('0' + i) + "^" + ('0' + i) + ",";

        else str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_MM.CBData = str;
    $c.stf.setObjectValue(cmb_MM, '0');
};
scwin.fn_CheckCond = function() {
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    //alert(getObjectValue(cmb_YYYY) +":"+ getObjectValue(cmb_MM));
    var url = "/DisclosureSearch.do?method=list4ESG" + "&inputMessageId=ESGDSCLLIST_INOUT" + "&outputMessageId=ESGDSCLLIST_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd) + "&STD_YYYY=" + $c.stf.getObjectValue(cmb_YYYY) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.mm = $c.stf.getObjectValue(cmb_MM);
    scwin.filterCnt = 0;
    $c.cm.ShowWin(grd_Grid);
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
};
scwin.doCntSet = function() {
    //txt_gen_duty
    var tmpBigYN = 'N'; //자산총액 2조원 이상여부
    var tmpFinYN = 'N'; //금융업종 여부
    var tmpGenDisclsYN = 'N'; //일반 기업지배구조보고서 제출여부
    var tmpFreeDisclsYN = 'N'; //자율 기업지배구조보고서 제출여부
    var cntGenBig = 0; //일반법인 자산총액 2조원 이상 개수
    var cntFinBig = 0; //금융업종 자산총액 2조원 이상 개수
    var cntGenDisclsSubmit = 0; //일반법인 기업지배 보고서 제출 개수
    var cntFinDisclsSubmit = 0; //금융업종 기업지배 보고서 제출 개수
    var cntGenDisclsNotSubmit = 0; //일반법인 기업지배 보고서 미제출 개수
    var cntFinDisclsNotSubmit = 0; //금융업종 기업지배 보고서 미제출 개수
    var cntGenFreeDisclsSubmit = 0; //일반법인 자율공시 기업지배 보고서 제출 개수
    var cntFinFreeDisclsSubmit = 0; //금융업종 자율공시 기업지배 보고서 제출 개수

    for (var i = 1; i <= scwin.filterCnt; i++) {
        tmpBigYN = dts_DsclList.getCellData(i, "BIG_YN");
        tmpFinYN = dts_DsclList.getCellData(i, "FIN_YN");
        tmpGenDisclsYN = dts_DsclList.getCellData(i, "ACPT_NOW_92014_YN");
        tmpFreeDisclsYN = dts_DsclList.getCellData(i, "ACPT_NOW_92011_YN");
        if (tmpFinYN == 'N') {
            if (tmpBigYN == 'Y') {
                cntGenBig++;
            }
            if (tmpGenDisclsYN == 'Y') {
                cntGenDisclsSubmit++;
            }
            if (tmpFreeDisclsYN == 'Y') {
                cntGenFreeDisclsSubmit++;
            }
        } else {
            if (tmpBigYN == 'Y') {
                cntFinBig++;
            }
            if (tmpGenDisclsYN == 'Y') {
                cntFinDisclsSubmit++;
            } else {
                cntFinDisclsNotSubmit++;
            }
            if (tmpFreeDisclsYN == 'Y') {
                cntFinFreeDisclsSubmit++;
            }
        }
    }

    //alert(under2cnt);
    txt_gen_duty.setValue(cntGenBig);
    txt_gen_submit.setValue(cntGenDisclsSubmit);
    txt_gen_notsubmit.setValue((cntGenBig - cntGenDisclsSubmit));
    txt_gen_submit_free.setValue(cntGenFreeDisclsSubmit);
    //금융회사의 경우 자산총액 값이 제대로 안들어와서 2조원 여부를 알 수 없어. 그냥 제출기업은 의무제출기업이라고 판단하기로 함.
    txt_fin_duty.setValue(cntFinDisclsSubmit);
    txt_fin_submit.setValue(cntFinDisclsSubmit);
    txt_fin_notsubmit.setValue((cntFinDisclsSubmit - cntFinDisclsSubmit)); //얜 뭐 항상 0이네..
    txt_fin_submit_free.setValue(cntFinFreeDisclsSubmit);
    txt_all.setValue(cntGenBig + cntFinDisclsSubmit);
    txt_all_submit.setValue(cntGenDisclsSubmit + cntFinDisclsSubmit);
    txt_all_not_submit.setValue((cntGenBig - cntGenDisclsSubmit) + (cntFinDisclsSubmit - cntFinDisclsSubmit));
    txt_all_free_submit.setValue((cntGenFreeDisclsSubmit + cntFinFreeDisclsSubmit));
    $c.cm.CloseWin(scwin.filterCnt, grd_Grid); //조회완료시 LOADING 이미지 종료
    $c.stf.FillGridHeaderTotalCntESG(scwin.filterCnt, panel_page); //총 건수

};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "ESG공시 목록", "", "8");
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        scwin.filterCnt = rowcount;
        dts_DsclList.UseFilter = true;
        //dts_DsclList.Filter();	
        scwin.doCntSet();
    }
};
scwin.img_Isu_Srh_onclick = function() {
    $c.cm.IsurcdSearch(txb_IsurCd, txb_com_abbrv);
};
scwin.txb_IsurCd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_IsurCd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_IsurCd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_IsurCd_onkeyup = function() {
    if (txb_IsurCd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetYYYY();
    scwin.fn_SetMM();
    $c.cm.fn_com_isur(txb_IsurCd, txb_com_abbrv);
    scwin.fn_CheckCond();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    var gAcptNo = 0;
    var tmpYN = 'N';
    if (colid == "ACPT_NOW_92014_YN") {
        tmpYN = dts_DsclList.getCellData(row, "ACPT_NOW_92014_YN");
        if (tmpYN == 'Y') {
            gAcptNo = dts_DsclList.getCellData(row, "NOW_92014_ACPT_NO");
            $c.stf.fn_OpenDisclViewer(gAcptNo, "R");
        }
    } else if (colid == "ACPT_NOW_92011_YN") {
        tmpYN = dts_DsclList.getCellData(row, "ACPT_NOW_92011_YN");
        if (tmpYN == 'Y') {
            gAcptNo = dts_DsclList.getCellData(row, "NOW_92011_ACPT_NO");
            $c.stf.fn_OpenDisclViewer(gAcptNo, "R");
        }
    } else if (colid == "BEF_DISCLS_YN") {
        tmpYN = dts_DsclList.getCellData(row, "BEF_DISCLS_YN");
        if (tmpYN == 'Y') {
            gAcptNo = dts_DsclList.getCellData(row, "BEF_ACPT_NO");
            $c.stf.fn_OpenDisclViewer(gAcptNo, "R");
        }
    }
};
scwin.dts_DsclList_OnFilter = function(row) {
    if (scwin.mm == "0") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_DsclList.getCellData(row, "ACNTCLS_MM") == scwin.mm) {
            scwin.filterCnt++;
            return true;
        } else {
            return false;
        }
    }
};
